import{_ as a,H as n,f as i,i as e}from"./chunks/framework.BH2BK_3i.js";const c=JSON.parse('{"title":"16｜对话引擎（上）：理解对话链路与流式技术选型","description":"","frontmatter":{},"headers":[{"level":2,"title":"对话引擎是什么","slug":"对话引擎是什么","link":"#对话引擎是什么","children":[]},{"level":2,"title":"对话引擎的完整链路","slug":"对话引擎的完整链路","link":"#对话引擎的完整链路","children":[]},{"level":2,"title":"数据结构设计","slug":"数据结构设计","link":"#数据结构设计","children":[]},{"level":2,"title":"流式响应：SSE完整解析","slug":"流式响应-sse完整解析","link":"#流式响应-sse完整解析","children":[{"level":3,"title":"SSE是什么","slug":"sse是什么","link":"#sse是什么","children":[]},{"level":3,"title":"为什么不用WebSocket","slug":"为什么不用websocket","link":"#为什么不用websocket","children":[]},{"level":3,"title":"SseEmitter的工作原理","slug":"sseemitter的工作原理","link":"#sseemitter的工作原理","children":[]},{"level":3,"title":"SseEmitter的三个坑","slug":"sseemitter的三个坑","link":"#sseemitter的三个坑","children":[]}]},{"level":2,"title":"扩展适配层：加Chat能力","slug":"扩展适配层-加chat能力","link":"#扩展适配层-加chat能力","children":[]},{"level":2,"title":"对话接口设计","slug":"对话接口设计","link":"#对话接口设计","children":[]},{"level":2,"title":"总结","slug":"总结","link":"#总结","children":[]},{"level":2,"title":"思考题","slug":"思考题","link":"#思考题","children":[]}],"relativePath":"ClaudeCode企业级全链路开发实战/16｜对话引擎（上）：理解对话链路与流式技术选型.md","filePath":"ClaudeCode企业级全链路开发实战/16｜对话引擎（上）：理解对话链路与流式技术选型.md","lastUpdated":1779815375000}'),t={name:"ClaudeCode企业级全链路开发实战/16｜对话引擎（上）：理解对话链路与流式技术选型.md"};function p(l,s,h,o,r,k){return n(),i("div",null,[...s[0]||(s[0]=[e(`<h1 id="_16-对话引擎-上-理解对话链路与流式技术选型" tabindex="-1">16｜对话引擎（上）：理解对话链路与流式技术选型 <a class="header-anchor" href="#_16-对话引擎-上-理解对话链路与流式技术选型" aria-label="Permalink to &quot;16｜对话引擎（上）：理解对话链路与流式技术选型&quot;">​</a></h1><p>你好，我是Robert。</p><p>上一讲我们创建了智能客服Agent，名字、Prompt、模型、参数都配好了，但它现在还不能说话。Agent只是一份配置，需要对话引擎来驱动它。</p><p>对话引擎是Hify最核心的模块。没有它，前面做的模型管理、适配层、Agent配置都只是准备工作。这一讲和下一讲会把对话引擎做完。</p><p>和15讲学Agent一样，我们先搞清楚对话引擎到底是什么，再动手。</p><h2 id="对话引擎是什么" tabindex="-1">对话引擎是什么 <a class="header-anchor" href="#对话引擎是什么" aria-label="Permalink to &quot;对话引擎是什么&quot;">​</a></h2><blockquote><p>在AI应用平台里，对话引擎是什么？它的职责是什么？和普通的HTTP接口调用有什么区别？</p></blockquote><p>Claude Code的回答帮我建立了认知：对话引擎不是一个简单的“转发器”，不是把用户的话原封不动发给LLM，再把回复原封不动传回来。它是连接用户和LLM的一条处理管道，中间要做很多事。</p><ol><li><p><strong>会话管理</strong>。用户和智能客服聊了十轮，这十轮属于同一次对话。对话引擎要维护“会话”的概念，哪些消息属于同一次对话、会话什么时候创建、什么时候结束。</p></li><li><p><strong>上下文拼装</strong>。LLM本身没有记忆。你问完“Hify怎么创建Agent”，再问“那怎么配置模型”，LLM不知道“那”指的是什么。对话引擎要把System Prompt +历史消息+当前消息拼成一个完整的messages数组，每次调用都带上上下文，让LLM “看起来”有记忆。</p></li><li><p><strong>流式响应</strong>。LLM生成一个完整回复可能要十几秒。如果等全部生成完再返回，用户要盯着空白页面干等。对话引擎要做流式推送，LLM生成一个字就推一个字给前端，用户看到的是像人打字一样一个字一个字冒出来。这就是ChatGPT的打字机效果。</p></li><li><p><strong>消息存储</strong>。对话结束后，用户消息和AI回复要持久化到数据库。用户下次打开能看到历史记录，管理员能做数据分析。</p></li></ol><p>和普通HTTP接口的核心区别： <strong>普通接口是请求-响应模式，一来一回就结束。对话引擎是长连接+流式，请求发出后，响应不是一次性返回的，而是一个字一个字持续推送，可能持续几十秒甚至一两分钟。这带来了完全不同的技术挑战：线程不能一直占着、连接不能提前断、前端要实时渲染。</strong></p><p>我追问了一个具体问题：</p><blockquote><p>对话引擎和LLM API的关系是什么？为什么不直接让前端调LLM API？</p></blockquote><p>Claude Code的回答点出了关键：直接让前端调LLM API有三个问题。</p><ol><li>API Key暴露在前端不安全。</li><li>每个LLM供应商的API格式不同，前端要适配多套格式。</li><li>没有上下文管理，前端每次要自己拼历史消息传给LLM，还要自己管会话。</li></ol><p>总结就是： <strong>对话引擎就是把这些脏活集中到后端处理，前端只需要发一条消息、接收一串流式回复</strong>。</p><h2 id="对话引擎的完整链路" tabindex="-1">对话引擎的完整链路 <a class="header-anchor" href="#对话引擎的完整链路" aria-label="Permalink to &quot;对话引擎的完整链路&quot;">​</a></h2><p>概念清楚了，让Claude Code帮我画出完整的技术链路：</p><blockquote><p>用户和一个Agent对话，从前端发消息到收到流式回复，中间每一步技术上发生了什么？从前端到Controller到Service到LLM再回来，逐步梳理。</p></blockquote><p>Claude Code给了一张非常完整的链路图：</p><div class="language-plaintext vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plaintext</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>用户输入 &quot;Hify 怎么创建 Agent？&quot;</span></span>
<span class="line"><span>    │</span></span>
<span class="line"><span>    ▼</span></span>
<span class="line"><span>[前端] POST /api/v1/chat/sessions/{sessionId}/messages</span></span>
<span class="line"><span>       接收: SSE 流式响应</span></span>
<span class="line"><span>    │</span></span>
<span class="line"><span>    ▼</span></span>
<span class="line"><span>[ChatService] ── 组装上下文 ──</span></span>
<span class="line"><span>    │  1. 查 session → 拿到 agentId</span></span>
<span class="line"><span>    │  2. 查 Agent → 拿到 systemPrompt、modelConfigId、参数</span></span>
<span class="line"><span>    │  3. 查 ModelConfig → 拿到 modelId、providerId</span></span>
<span class="line"><span>    │  4. 查 Provider → 拿到 baseUrl、authConfig</span></span>
<span class="line"><span>    │  5. 从 Redis 取最近 N 轮历史消息</span></span>
<span class="line"><span>    │</span></span>
<span class="line"><span>    ▼</span></span>
<span class="line"><span>[ChatService] ── 写入用户消息 ──</span></span>
<span class="line"><span>    │  INSERT chat_message(role=&#39;user&#39;, content)</span></span>
<span class="line"><span>    │</span></span>
<span class="line"><span>    ▼</span></span>
<span class="line"><span>[ChatService] ── 构造 LLM 请求 ──</span></span>
<span class="line"><span>    │  messages = [</span></span>
<span class="line"><span>    │    { role: &quot;system&quot;,    content: agent.systemPrompt },</span></span>
<span class="line"><span>    │    { role: &quot;user&quot;,      content: &quot;上上轮问题&quot; },</span></span>
<span class="line"><span>    │    { role: &quot;assistant&quot;, content: &quot;上上轮回复&quot; },</span></span>
<span class="line"><span>    │    { role: &quot;user&quot;,      content: &quot;Hify 怎么创建 Agent？&quot; }</span></span>
<span class="line"><span>    │  ]</span></span>
<span class="line"><span>    │</span></span>
<span class="line"><span>    ▼</span></span>
<span class="line"><span>[LlmHttpClient] ── 流式调用 LLM ──</span></span>
<span class="line"><span>    │  llmExecutor 线程池（和业务线程隔离）</span></span>
<span class="line"><span>    │  Resilience4j 熔断器包裹</span></span>
<span class="line"><span>    │</span></span>
<span class="line"><span>    ▼</span></span>
<span class="line"><span>[LLM API] 返回 SSE 流 → 边收边推给前端</span></span>
<span class="line"><span>    │</span></span>
<span class="line"><span>    ▼</span></span>
<span class="line"><span>[ChatService] ── 流结束后 ──</span></span>
<span class="line"><span>    │  INSERT chat_message(role=&#39;assistant&#39;, content=完整回复)</span></span>
<span class="line"><span>    │  更新 Redis 历史消息</span></span></code></pre></div><p>六步：查配置 → 取历史 → 写用户消息 → 拼装请求 → 流式调用 → 存回复。</p><p>其中第5步（从Redis取历史）和第6步（更新Redis）是上下文管理的核心，下一讲展开。这一讲聚焦第4步，流式调用和推送的技术方案。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E4%BC%81%E4%B8%9A%E7%BA%A7%E5%85%A8%E9%93%BE%E8%B7%AF%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/968737/19fdf784d598e4f9f298fe78a7800912.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E4%BC%81%E4%B8%9A%E7%BA%A7%E5%85%A8%E9%93%BE%E8%B7%AF%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/968737/19fdf784d598e4f9f298fe78a7800912.png" alt=""></a></p><h2 id="数据结构设计" tabindex="-1">数据结构设计 <a class="header-anchor" href="#数据结构设计" aria-label="Permalink to &quot;数据结构设计&quot;">​</a></h2><p>在深入流式技术之前，先把数据模型定下来。</p><blockquote><p>对话引擎需要哪些表？会话和消息怎么存？消息表需要哪些字段？</p></blockquote><p>现有的schema.sql里已经有了chat_session和chat_message的基础结构。Claude Code分析后建议补几个字段：</p><ul><li><p>chat_session补status。流式响应中途出错时需要记录会话状态。ACTIVE / ARCHIVED两个状态够用。</p></li><li><p>chat_message补finish_reason和latency_ms。finish_reason记录LLM为什么停止——stop（正常结束）、length（超max_tokens截断）、error（调用失败），调试和后续计费都用到。latency_ms记录响应耗时，性能分析用。</p></li><li><p>content从TEXT改LONGTEXT。 一条assistant消息可能几千字，代码生成场景可能更长，LONGTEXT彻底避免截断。</p></li></ul><p>SQL Schema如下：</p><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">chat_session</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  id          </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">bigint</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> PK</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  agent_id    </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">bigint</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">          -- 关联 agent</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  title       </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">varchar</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">200</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)    </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">-- 首条消息前 20 字自动生成</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  status</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">      varchar</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">20</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)     </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">-- ACTIVE / ARCHIVED</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  deleted </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> created_at </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> updated_at</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">chat_message</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  id            </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">bigint</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> PK</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  session_id    </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">bigint</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">         -- 关联 chat_session</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  role</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">          varchar</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">20</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)    </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">-- user / assistant / system</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  content       longtext</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  tokens        </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">int</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">            -- token 数（上下文管理用）</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  finish_reason </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">varchar</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">20</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)    </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">-- stop / length / error</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  latency_ms    </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">int</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">            -- 响应耗时 ms</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  deleted </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> created_at </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> updated_at</span></span></code></pre></div><p>几个设计决策：role只有user / assistant / system，和OpenAI的messages格式直接对齐。system消息一般不存库，由Agent.systemPrompt每次动态注入。token数在流式响应结束后由LLM返回的usage写入。会话title取第一条user消息前20字，不额外消耗token。</p><p>chat_message是增长最快的表，这一点在05讲数据库规范里已经预判了。</p><h2 id="流式响应-sse完整解析" tabindex="-1">流式响应：SSE完整解析 <a class="header-anchor" href="#流式响应-sse完整解析" aria-label="Permalink to &quot;流式响应：SSE完整解析&quot;">​</a></h2><p>这是对话引擎技术含量最高的部分。大部分后端工程师写过无数的请求-响应接口，但没写过流式推送。先搞清楚原理。</p><h3 id="sse是什么" tabindex="-1">SSE是什么 <a class="header-anchor" href="#sse是什么" aria-label="Permalink to &quot;SSE是什么&quot;">​</a></h3><blockquote><p>SSE（Server-Sent Events）的工作原理是什么？和普通HTTP请求有什么区别？数据格式是什么样的？</p></blockquote><p>Claude Code的解释：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E4%BC%81%E4%B8%9A%E7%BA%A7%E5%85%A8%E9%93%BE%E8%B7%AF%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/968737/c016031ac44dd32e8578eb29b0c5f93a.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E4%BC%81%E4%B8%9A%E7%BA%A7%E5%85%A8%E9%93%BE%E8%B7%AF%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/968737/c016031ac44dd32e8578eb29b0c5f93a.png" alt=""></a></p><p>普通HTTP请求是“一来一回”——客户端发请求，服务端返回完整响应，连接关闭。SSE是“一来持续回”——客户端发请求，服务端保持连接不关闭，持续往客户端推数据，直到主动关闭。</p><p>数据格式很简单，每条消息以 <code>data:</code> 开头，用两个换行分隔：</p><div class="language-plaintext vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plaintext</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>data: {&quot;type&quot;:&quot;delta&quot;,&quot;content&quot;:&quot;在&quot;}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>data: {&quot;type&quot;:&quot;delta&quot;,&quot;content&quot;:&quot;Hify&quot;}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>data: {&quot;type&quot;:&quot;delta&quot;,&quot;content&quot;:&quot;中&quot;}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>data: {&quot;type&quot;:&quot;done&quot;,&quot;finishReason&quot;:&quot;stop&quot;}</span></span></code></pre></div><p>前端用EventSource API接收，浏览器原生支持，不需要额外依赖：</p><div class="language-javascript vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> es</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> new</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> EventSource</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;/api/v1/chat/sessions/1/messages/stream&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">es.onmessage </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> e </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=&amp;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">gt; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">appendToken</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">JSON</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">parse</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(e.data).content)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">es.onerror </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> () </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=&amp;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">gt; es.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">close</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">()</span></span></code></pre></div><h3 id="为什么不用websocket" tabindex="-1">为什么不用WebSocket <a class="header-anchor" href="#为什么不用websocket" aria-label="Permalink to &quot;为什么不用WebSocket&quot;">​</a></h3><blockquote><p>AI对话的流式响应，用SSE还是WebSocket？</p></blockquote><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E4%BC%81%E4%B8%9A%E7%BA%A7%E5%85%A8%E9%93%BE%E8%B7%AF%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/968737/f039c6f1767099474f974f0ffee020b7.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E4%BC%81%E4%B8%9A%E7%BA%A7%E5%85%A8%E9%93%BE%E8%B7%AF%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/968737/f039c6f1767099474f974f0ffee020b7.png" alt=""></a></p><p><strong>AI 对话就是“客户端发一条消息，服务端流式回复”，典型的单向推送。用户发消息走普通 POST 请求就行，不需要双向通信。WebSocket 的双向能力在这里完全用不上</strong>。</p><p>业界验证：OpenAI、Anthropic、Dify，所有主流AI对话产品都选SSE。</p><h3 id="sseemitter的工作原理" tabindex="-1">SseEmitter的工作原理 <a class="header-anchor" href="#sseemitter的工作原理" aria-label="Permalink to &quot;SseEmitter的工作原理&quot;">​</a></h3><blockquote><p>Spring MVC的SseEmitter怎么工作？生命周期是什么样的？</p></blockquote><p>SseEmitter本质是一个长连接容器。Controller方法返回SseEmitter对象后，Spring不会关闭HTTP连接，而是持有它。后续代码通过 <code>emitter.send()</code> 往这个连接里推数据，最后 <code>emitter.complete()</code> 关闭连接。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E4%BC%81%E4%B8%9A%E7%BA%A7%E5%85%A8%E9%93%BE%E8%B7%AF%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/968737/b1d674e91006e60b1f0dc7e00eb8d5f2.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E4%BC%81%E4%B8%9A%E7%BA%A7%E5%85%A8%E9%93%BE%E8%B7%AF%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/968737/b1d674e91006e60b1f0dc7e00eb8d5f2.png" alt=""></a></p><p>关键在于线程切换。Tomcat的请求线程创建SseEmitter后立刻返回，不能让Tomcat线程等LLM响应，那要等几十秒，线程池会被占满。实际的LLM调用在llmExecutor线程池里异步执行：</p><div class="language-plaintext vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plaintext</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Tomcat 线程:</span></span>
<span class="line"><span>  创建 SseEmitter(120s) → 提交任务给 llmExecutor → return emitter</span></span>
<span class="line"><span>  （线程释放，可以处理其他请求）</span></span>
<span class="line"><span></span></span>
<span class="line"><span>llmExecutor 线程:</span></span>
<span class="line"><span>  调用 LLM stream API → 收到 delta → emitter.send(delta)</span></span>
<span class="line"><span>                       → 收到 delta → emitter.send(delta)</span></span>
<span class="line"><span>                       → 收到 [DONE] → 存消息 → emitter.complete()</span></span></code></pre></div><p>这就是为什么10讲要配独立的llmExecutor线程池。LLM调用在自己的池子里跑，不占Tomcat线程，管理页面不受影响。</p><h3 id="sseemitter的三个坑" tabindex="-1">SseEmitter的三个坑 <a class="header-anchor" href="#sseemitter的三个坑" aria-label="Permalink to &quot;SseEmitter的三个坑&quot;">​</a></h3><p>Claude Code <strong>特别提醒了</strong> 三个必须处理的问题：</p><ol><li><p><strong>超时</strong>。SseEmitter默认超时30秒。LLM生成一个长回复可能要一两分钟，30秒一到连接直接断了用户看到半截回复。必须设长， <code>new SseEmitter(120_000L)</code>，120秒。</p></li><li><p><strong>客户端断开</strong>。用户对话到一半关了浏览器标签页，HTTP连接断了。但llmExecutor线程不知道，它还在调LLM，每收到一个delta就 <code>emitter.send()</code>，直到IOException。如果不catch这个异常并停止LLM调用，线程会白跑到LLM输出完，浪费llmExecutor的线程资源。必须在send的catch里停止LLM调用并释放线程。</p></li><li><p><strong>Nginx缓冲</strong>。这是最容易被忽略的。Nginx默认会缓冲上游响应，收集一批数据后才一次性发给客户端。结果用户看到的是“等了十几秒突然全部内容一起出现”，流式效果完全失效。必须在Nginx配置里关掉缓冲：</p></li></ol><div class="language-nginx vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">nginx</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">location</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> /api/ </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    proxy_pass </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">http://backend;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    proxy_buffering </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">off</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    proxy_cache </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">off</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    proxy_read_timeout </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">120s</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>还有一个很细的细节： <strong>事务不要跨SseEmitter。</strong>@Transactional方法里不要直接返回SseEmitter，事务提交时机和流结束时机不同，会导致事务提前提交或连接超时。要把写消息的操作拆成独立方法调用。</p><h2 id="扩展适配层-加chat能力" tabindex="-1">扩展适配层：加Chat能力 <a class="header-anchor" href="#扩展适配层-加chat能力" aria-label="Permalink to &quot;扩展适配层：加Chat能力&quot;">​</a></h2><p>14讲做的ProviderAdapter接口只有testConnection和listModels。对话引擎需要chat（同步）和streamChat（流式）。</p><blockquote><p>给ProviderAdapter接口扩展chat和streamChat方法。设计ChatRequest和ChatResponse DTO。</p></blockquote><ul><li><p>ChatRequest：modelId、messages（List，每条含role和content）、temperature、maxTokens。</p></li><li><p>ChatResponse：content（完整回复文本）、finishReason（stop/length/error）、completionTokens。</p></li></ul><p><strong>streamChat的核心设计：</strong> 接收一个 <code>Consumer&amp;lt;String&gt; onChunk</code> 回调。适配层每收到LLM的一段delta文本就调一次onChunk，ChatService在onChunk里调 <code>emitter.send()</code> 推给前端。流结束后返回完整的ChatResponse。</p><p>各Adapter的流式格式差异很大，这是最需要仔细review的部分：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E4%BC%81%E4%B8%9A%E7%BA%A7%E5%85%A8%E9%93%BE%E8%B7%AF%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/968737/530792ef9c1740cfe97736f65eafd0d1.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E4%BC%81%E4%B8%9A%E7%BA%A7%E5%85%A8%E9%93%BE%E8%B7%AF%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/968737/530792ef9c1740cfe97736f65eafd0d1.png" alt=""></a></p><p>先实现OpenAiAdapter的streamChat，review通过后其他三个批量生成。和14讲同样的模式。</p><p>生成后怎么验证？流式代码涉及多线程和回调，不好直接读。用一个高效方法：让写代码的AI解释它自己的代码。</p><blockquote><p>逐步解释你刚才生成的streamChat代码。特别说明：线程是怎么切换的、如果LLM中途抛异常会怎样、如果客户端断开会怎样。</p></blockquote><p>它解释一遍，你听逻辑。如果解释里有自相矛盾的地方（比如“异常时调completeWithError”但代码里没有catch），说明代码有bug。这比自己逐行读不熟悉的异步代码高效得多。</p><h2 id="对话接口设计" tabindex="-1">对话接口设计 <a class="header-anchor" href="#对话接口设计" aria-label="Permalink to &quot;对话接口设计&quot;">​</a></h2><p>最后定接口格式。先看业界怎么做。</p><blockquote><p>ChatGPT API和Dify的对话接口怎么设计的？</p></blockquote><p>OpenAI：无状态。每次传完整messages数组，不管会话。好处是简单，坏处是历史管理全甩给调用方。</p><p>Dify：有状态。用conversation_id关联，服务端维护历史，前端只传当前消息。好处是前端简单，坏处是后端要管会话。</p><p>Hify选有状态，接口RESTful风格：</p><div class="language-plaintext vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plaintext</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>POST /api/v1/chat/sessions                    # 创建会话</span></span>
<span class="line"><span>POST /api/v1/chat/sessions/{id}/messages      # 发消息</span></span>
<span class="line"><span>GET  /api/v1/chat/sessions                    # 会话列表</span></span>
<span class="line"><span>GET  /api/v1/chat/sessions/{id}/messages      # 历史消息</span></span>
<span class="line"><span>DELETE /api/v1/chat/sessions/{id}             # 删除会话</span></span></code></pre></div><p>发消息请求体极简：</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;content&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Hify 怎么创建 Agent？&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;stream&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>比Dify更简单，不需要user字段（没有多租户），不需要inputs（没有变量注入），session已经关联了agentId不需要再传。</p><p>流式响应格式：</p><div class="language-plaintext vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plaintext</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>data: {&quot;type&quot;:&quot;delta&quot;,&quot;content&quot;:&quot;在&quot;}</span></span>
<span class="line"><span>data: {&quot;type&quot;:&quot;delta&quot;,&quot;content&quot;:&quot;Hify&quot;}</span></span>
<span class="line"><span>data: {&quot;type&quot;:&quot;delta&quot;,&quot;content&quot;:&quot;中...&quot;}</span></span>
<span class="line"><span>data: {&quot;type&quot;:&quot;done&quot;,&quot;finishReason&quot;:&quot;stop&quot;,&quot;latencyMs&quot;:1240}</span></span></code></pre></div><p>最后一条done事件带finishReason和latencyMs，前端据此停止loading并显示完整消息。</p><p>消息存储选流结束后同步存MySQL。20-50人同步写没压力，不引入消息队列。</p><h2 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">​</a></h2><p>这一讲做了四件事：</p><ol><li>理解对话引擎。不是转发器，是处理管道——会话管理、上下文拼装、流式推送、消息存储。</li><li>设计数据模型。在已有表基础上补了status、finish_reason、latency_ms、LONGTEXT。</li><li>搞懂流式响应。SSE的原理、和WebSocket的区别、SseEmitter的线程模型和三个坑（超时、客户端断开、Nginx缓冲）、事务不跨SseEmitter。</li><li>扩展适配层和定接口。ProviderAdapter加Chat / streamChat，四个Adapter的流式格式差异。RESTful有状态接口设计。</li></ol><p>概念清楚了、表设计好了、流式方案定了、适配层扩展完了、接口格式定了。下一讲直接执行，CRUD实现、上下文管理、跑通完整链路，让智能客服真正开口说话。</p><p>方法论上的新收获： <strong>验证不熟悉的代码，让AI解释它自己写的代码，你听逻辑找矛盾。流式响应、回调、多线程这些不常写的代码，用这个方法比自己硬读高效得多。</strong></p><h2 id="思考题" tabindex="-1">思考题 <a class="header-anchor" href="#思考题" aria-label="Permalink to &quot;思考题&quot;">​</a></h2><ol><li>SseEmitter超时设了120秒，但有些复杂问题LLM可能需要更长时间。超时应该固定还是动态？</li><li>如果要支持“停止生成”（用户中断AI回复），技术上怎么实现？需要改适配层吗？</li><li>四个Adapter的流式格式都不同，如果以后有新供应商用了第五种格式，现在的架构能不能低成本扩展？</li></ol><p>期待你的分享！如果今天的课程让你有所收获，也欢迎转发给有需要的朋友，邀请他来一起学习，我们下节课再见！</p>`,93)])])}const E=a(t,[["render",p]]);export{c as __pageData,E as default};
